<?php
require_once __DIR__ . '/app-functions.php';
session_start();
if (empty($_SESSION['email'])) { header('Location: login.php'); exit; }
ensureNotificationTable(); $conn = dbConnect(); $email = $_SESSION['email'];
if (empty($_SESSION['notifications_csrf'])) $_SESSION['notifications_csrf'] = bin2hex(random_bytes(32));
if ($_SERVER['REQUEST_METHOD'] === 'POST' && hash_equals($_SESSION['notifications_csrf'], $_POST['csrf'] ?? '')) {
    $action = $_POST['action'] ?? '';
    if ($action === 'mark_all_read') { $stmt = mysqli_prepare($conn, "UPDATE notifications SET is_read=1 WHERE recipient_type='customer' AND recipient_email=?"); mysqli_stmt_bind_param($stmt, 's', $email); mysqli_stmt_execute($stmt); $_SESSION['notification_notice'] = 'All notifications are marked as read.'; }
    if ($action === 'delete_one') { $id = (int) ($_POST['notification_id'] ?? 0); $stmt = mysqli_prepare($conn, "DELETE FROM notifications WHERE notification_id=? AND recipient_type='customer' AND recipient_email=?"); mysqli_stmt_bind_param($stmt, 'is', $id, $email); mysqli_stmt_execute($stmt); $_SESSION['notification_notice'] = 'Notification deleted.'; }
    if ($action === 'delete_all') { $stmt = mysqli_prepare($conn, "DELETE FROM notifications WHERE recipient_type='customer' AND recipient_email=?"); mysqli_stmt_bind_param($stmt, 's', $email); mysqli_stmt_execute($stmt); $_SESSION['notification_notice'] = 'All notifications were cleared.'; }
    header('Location: notifications.php'); exit;
}
$notice = $_SESSION['notification_notice'] ?? ''; unset($_SESSION['notification_notice']);
$stmt = mysqli_prepare($conn, "SELECT * FROM notifications WHERE recipient_type='customer' AND recipient_email=? ORDER BY created_at DESC LIMIT 50"); mysqli_stmt_bind_param($stmt, 's', $email); mysqli_stmt_execute($stmt); $notifications = mysqli_fetch_all(mysqli_stmt_get_result($stmt), MYSQLI_ASSOC);
$unreadCount = count(array_filter($notifications, function ($notification) { return empty($notification['is_read']); }));
$pageTitle='Notifications'; $activePage=''; $bodyClass='notifications-page'; $pageStyles=array('css/notifications.css'); include __DIR__ . '/includes/public-header.php';
?>
<main class="notifications-main"><header class="notifications-heading"><div><p>Account updates</p><h1>Notifications</h1><span><?php echo $unreadCount ? $unreadCount . ' unread update' . ($unreadCount === 1 ? '' : 's') : 'You are all caught up'; ?></span></div><?php if ($notifications) { ?><div class="notification-heading-actions"><?php if ($unreadCount) { ?><form method="post"><input type="hidden" name="csrf" value="<?php echo htmlspecialchars($_SESSION['notifications_csrf'],ENT_QUOTES,'UTF-8'); ?>"><input type="hidden" name="action" value="mark_all_read"><button class="notifications-read-all" type="submit"><i class="bi bi-check2-all" aria-hidden="true"></i>Mark all read</button></form><?php } ?><form method="post" onsubmit="return confirm('Clear all notifications? This cannot be undone.');"><input type="hidden" name="csrf" value="<?php echo htmlspecialchars($_SESSION['notifications_csrf'],ENT_QUOTES,'UTF-8'); ?>"><input type="hidden" name="action" value="delete_all"><button class="notifications-clear-all" type="submit"><i class="bi bi-trash3" aria-hidden="true"></i>Clear all</button></form></div><?php } ?></header><?php if($notice){?><p class="notifications-notice" role="status"><i class="bi bi-check-circle" aria-hidden="true"></i><?php echo htmlspecialchars($notice,ENT_QUOTES,'UTF-8'); ?></p><?php } ?><?php if(!$notifications){?><section class="notifications-empty"><i class="bi bi-bell-slash" aria-hidden="true"></i><h2>No updates yet</h2><p>Order, payment, and delivery updates will appear here.</p><a href="menu.php">Browse menu</a></section><?php } else { ?><section class="notifications-list" aria-label="Notification list"><?php foreach($notifications as $notification){ $isUnread = empty($notification['is_read']); ?><article class="notification-item<?php echo $isUnread ? ' is-unread' : ''; ?>"><div class="notification-icon"><i class="bi <?php echo $isUnread ? 'bi-bell-fill' : 'bi-bell'; ?>" aria-hidden="true"></i></div><div class="notification-copy"><div class="notification-title-row"><strong><?php echo htmlspecialchars($notification['title'],ENT_QUOTES,'UTF-8'); ?></strong><?php if($isUnread){?><span>New</span><?php }?></div><p><?php echo htmlspecialchars($notification['body'],ENT_QUOTES,'UTF-8'); ?></p><time datetime="<?php echo htmlspecialchars($notification['created_at'],ENT_QUOTES,'UTF-8'); ?>"><i class="bi bi-clock" aria-hidden="true"></i><?php echo date('d M Y, h:i A', strtotime($notification['created_at'])); ?></time></div><div class="notification-actions"><?php if($notification['link_path']){?><a class="notification-link" href="<?php echo htmlspecialchars($notification['link_path'],ENT_QUOTES,'UTF-8'); ?>">View update <i class="bi bi-arrow-right" aria-hidden="true"></i></a><?php }?><form method="post" onsubmit="return confirm('Delete this notification?');"><input type="hidden" name="csrf" value="<?php echo htmlspecialchars($_SESSION['notifications_csrf'],ENT_QUOTES,'UTF-8'); ?>"><input type="hidden" name="action" value="delete_one"><input type="hidden" name="notification_id" value="<?php echo (int) $notification['notification_id']; ?>"><button class="notification-delete" type="submit" aria-label="Delete notification" title="Delete notification"><i class="bi bi-trash3" aria-hidden="true"></i></button></form></div></article><?php }?></section><?php } ?></main>
<?php include __DIR__ . '/includes/public-footer.php'; ?>
